{ 
    json='{' ;
    first=1;
    while IFS= read -r line; do
        line=$(echo "$line" | sed -e 's/^\s*//' -e 's/\s*$//');
        [ -z "$line" ] && continue;
        case "$line" in "#"*) continue;; esac;
        key=${line%%=*};
        value=${line#*=};
        # escape double quotes and backslashes in value
        esc_value=$(printf '%s' "$value" | sed 's/\\/\\\\/g; s/"/\\"/g');
        esc_key=$(printf '%s' "$key" | sed 's/\\/\\\\/g; s/"/\\"/g');
        if [ $first -eq 1 ]; then
            json="$json\"$esc_key\":\"$esc_value\"";
            first=0;
        else
            json="$json,\"$esc_key\":\"$esc_value\"";
        fi;
    done < .env.test;
    json="$json}";
    echo "$json";
}

